function serializeQuerystring(querystring) {
  var parts = [];
  for (var key in querystring) {
    if (!Object.prototype.hasOwnProperty.call(querystring, key)) {
      continue;
    }
    var entry = querystring[key];
    if (entry && entry.multiValue) {
      for (var i = 0; i < entry.multiValue.length; i++) {
        var item = entry.multiValue[i];
        parts.push(item.value ? key + "=" + item.value : key);
      }
    } else if (entry) {
      parts.push(entry.value ? key + "=" + entry.value : key);
    }
  }
  return parts.length > 0 ? "?" + parts.join("&") : "";
}

function handler(event) {
  var request = event.request;
  var host = request.headers.host && request.headers.host.value;

  if (host === "www.brimax.life") {
    return {
      statusCode: 301,
      statusDescription: "Moved Permanently",
      headers: {
        location: {
          value: "https://brimax.life" + request.uri + serializeQuerystring(request.querystring || {})
        }
      }
    };
  }

  if (host !== "brimax.life") {
    return {
      statusCode: 403,
      statusDescription: "Forbidden",
      headers: {
        "content-type": {
          value: "text/plain; charset=utf-8"
        }
      },
      body: "Forbidden"
    };
  }

  return request;
}
